// Golden master of CURRENT behaviour. Do not "fix" expectations; a failure means behaviour changed.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// Hand-written fake of the downstream pricing service (unit price in euros per sku).
const prices = { A: 10, B: 25, C: 0.1, D: 33.33, E: 100, F: 50.5 }
const pricing = { priceOf: async (sku) => prices[sku] }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://127.0.0.1:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

