  method: 'POST', headers: { 'content-type': 'application/json' }, body: raw ?? JSON.stringify(body),
})
const total = async (items) => {
  const res = await post({ items })
  assert.equal(res.status, 201)
  return (await res.json()).total
}

test('POST /orders 201: shape, id sequence, JSON content-type', async () => {
  const res = await post({ items: [{ sku: 'A', qty: 2 }] })
  assert.equal(res.status, 201)
  assert.match(res.headers.get('content-type'), /application\/json/)
  const body = await res.json()
  assert.deepEqual(Object.keys(body).sort(), ['id', 'items', 'total'])
  assert.deepEqual(body.items, [{ sku: 'A', qty: 2 }])
  assert.equal(body.total, 20)
  assert.equal(typeof body.id, 'string')
  const next = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  assert.equal(Number(next.id), Number(body.id) + 1)
})

test('total sums unit price * qty over all items', async () => {
  assert.equal(await total([{ sku: 'A', qty: 3 }, { sku: 'B', qty: 2 }]), 80)
})

test('no discount at or below 100 (threshold is strict >)', async () => {
  assert.equal(await total([{ sku: 'E', qty: 1 }]), 100)
  assert.equal(await total([{ sku: 'A', qty: 10 }]), 100)
})

test('10% discount on the WHOLE order once total is above 100', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — crossing 100 makes the order cheaper:
  // 100 pays 100, but 101 pays 90 (flat 10% on everything, no tiers, cliff at the threshold).
  assert.equal(await total([{ sku: 'E', qty: 1 }, { sku: 'C', qty: 10 }]), 90) // 101 -> 90.9 -> 90
  assert.equal(await total([{ sku: 'B', qty: 8 }]), 180) // 200 -> 180
  assert.equal(await total([{ sku: 'A', qty: 100 }]), 900) // 1000 -> 900
})

test('discounted total is floored, never rounded', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — Math.floor drops cents (total is whole euros)
  // and always rounds in the customer's favour on discounted orders: 101.5 -> 91.35 -> 91.
  assert.equal(await total([{ sku: 'F', qty: 2 }, { sku: 'C', qty: 5 }]), 91) // 101.5
  assert.equal(await total([{ sku: 'D', qty: 3 }]), 99) // 99.99 undiscounted -> 99, not 100
  assert.equal(await total([{ sku: 'D', qty: 4 }]), 119) // 133.32 -> 119.988 -> 119
})

test('floating point error leaks into totals', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — binary floats: 0.1 * 3 = 0.30000000000000004 then floored.
  assert.equal(await total([{ sku: 'C', qty: 30 }]), 3) // 3.0000000000000004 -> 3
  assert.equal(await total([{ sku: 'C', qty: 1000 }]), 90) // 100 undiscounted? 0.1*1000 = 100 exactly -> no discount
})

test('qty is not validated: zero, negative, fractional and string quantities are accepted', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — no validation of qty or sku.
  assert.equal(await total([{ sku: 'A', qty: 0 }]), 0)
  assert.equal(await total([{ sku: 'A', qty: -3 }]), -30)
  assert.equal(await total([{ sku: 'A', qty: 1.5 }]), 15)
  assert.equal(await total([{ sku: 'A', qty: '2' }]), 20)
})

test('unknown sku (price undefined) yields a null total with 201', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — NaN total serialises as null.
  const res = await post({ items: [{ sku: 'ZZZ', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})

test('POST /orders 400 for missing, empty, non-array items and invalid JSON', async () => {
  for (const res of [await post({}), await post({ items: [] }), await post({ items: 'x' }), await post(null, '{not json')]) {
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('GET /orders/:id returns the stored order', async () => {
  const created = await (await post({ items: [{ sku: 'B', qty: 8 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), created)
})

test('GET /orders/:id for unknown id is 200 with an error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — "not found" is returned with status 200, not 404.
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unrouted requests are 404 no route', async () => {
  for (const [method, path] of [['GET', '/nope'], ['GET', '/orders'], ['DELETE', '/orders/1'], ['POST', '/orders/1']]) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404, `${method} ${path}`)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})
EOF
